export type NoneReturnValuesOption = 'NONE';
export type AllOldReturnValuesOption = 'ALL_OLD';
export type UpdatedOldReturnValuesOption = 'UPDATED_OLD';
export type AllNewReturnValuesOption = 'ALL_NEW';
export type UpdatedNewReturnValuesOption = 'UPDATED_NEW';
export type ReturnValuesOption = NoneReturnValuesOption | AllOldReturnValuesOption | UpdatedOldReturnValuesOption | AllNewReturnValuesOption | UpdatedNewReturnValuesOption;
export declare const parseReturnValuesOption: <ALLOWED_RETURN_VALUES_OPTION extends ReturnValuesOption>(allowedReturnValuesOptions: Set<ALLOWED_RETURN_VALUES_OPTION>, returnValues: ALLOWED_RETURN_VALUES_OPTION) => ALLOWED_RETURN_VALUES_OPTION;
